import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from lesson_authoring import bi as B
LESSONS={}
def F(s): return s.split('¦')
def C(en,ass,text,translation,scene=None):
 return {'title':[en,ass],'text':[[text,translation]],**({'scene':scene} if scene else {'art':'scroll'})}
def O(q,a,items,ans,why,aw):
 return {'type':'odd','q':B(q,a),'options':[B(*x) for x in items],'answer':ans,'why':B(why,aw)}
def W(clues,opts,ans,why,aw):
 return {'type':'whoami','clues':[B(*c) for c in clues],'options':[B(*x) for x in opts],'answer':ans,'why':B(why,aw)}
def T(anchors,items,why,aw):
 return {'type':'timeline','anchors':[{'y':str(y),'l':B(e,a)} for y,e,a in anchors],'items':[{'t':B(e,a),'slot':slot} for e,a,slot in items],'why':B(why,aw)}
def U(title,cards,facts,trap,why,interaction,connections):
 return {'title':title,'cards':cards,'facts':[F(f) for f in facts], 'trap':{'statement':trap,'why':why},'interaction':interaction,'connections':connections}
def add(n,title,span,units,sources):
 for i,u in enumerate(units,1): u['id']=f'u{i}'
 LESSONS[n]={'title':title,'span':span,'units':units,'source_keys':sources}
